<div class="page-heading"><div><div class="eyebrow">COMPETICIÓN / HISTORIAL</div><h1>Registro de <em>scrims</em></h1><p>Consulta el historial competitivo del equipo.</p></div><?php if(isCoach()):?><a class="btn btn-primary" href="<?=e(url('scrim-crear'))?>">+ Nueva scrim</a><?php endif;?></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>FECHA</th><th>MAPA</th><th>RIVAL</th><th>MARCADOR</th><th>RESULTADO</th><th>ACCIONES</th></tr></thead><tbody><?php foreach($games as $g):?><tr><td><?=e($g['fecha'])?></td><td><strong><?=e($g['nombre_mapa'])?></strong></td><td><?=e($g['equipo_rival'])?></td><td><strong><?=e($g['rondas_ganadas'])?> — <?=e($g['rondas_perdidas'])?></strong></td><td><span class="chip <?=e(strtolower($g['resultado']))?>"><?=e($g['resultado'])?></span></td><td><div class="actions"><a class="btn small" href="<?=e(url('scrim-ver',['id'=>$g['id_partida']]))?>">Ver</a><?php if(isCoach()):?><form method="post" action="<?=e(url('scrim-eliminar'))?>" data-confirm="¿Eliminar esta scrim y todas sus estadísticas?"><?=csrfField()?><input type="hidden" name="id" value="<?=e($g['id_partida'])?>"><button class="btn danger small">Eliminar</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$games):?><tr><td colspan="6">Aún no hay scrims registradas.</td></tr><?php endif;?></tbody></table></div></section>
